def matches(rule,envelope):
    pattern=rule['pattern']
    if not isinstance(pattern,dict) or not {'source','detail-type'}<=set(pattern) or set(pattern)-{'source','detail-type','detail'}:raise ValueError('unsupported pattern projection')
    def alternatives(value):
        if not isinstance(value,list) or not value or any(not isinstance(x,str) for x in value):raise ValueError('literal string alternatives only')
    alternatives(pattern['source']);alternatives(pattern['detail-type'])
    detail=pattern.get('detail',{})
    if not isinstance(detail,dict) or any(not isinstance(k,str) or not k or '.' in k for k in detail):raise ValueError('single-level detail projection required')
    for values in detail.values():alternatives(values)
    if rule['state'] not in ('ENABLED','DISABLED'):raise ValueError('unsupported rule state')
    if rule['bus_arn']!=envelope['bus_arn'] or rule['state']!='ENABLED':return False
    event=envelope['event']
    if event.get('source') not in pattern['source'] or event.get('detail-type') not in pattern['detail-type']:return False
    values=event.get('detail',{})
    if not isinstance(values,dict):return False
    return all(isinstance(values.get(key),str) and values[key] in choices for key,choices in detail.items())
