import re
def credential_source(definition,caller,operation):
    if caller=='agent' and operation in ('pull-image','publish-logs','inject-secret'):field='executionRoleArn'
    elif caller=='application' and isinstance(operation,str) and operation:field='taskRoleArn'
    else:raise ValueError('unsupported caller or operation')
    role=definition.get(field)
    if not isinstance(role,str) or not re.fullmatch(r'arn:aws:iam::'+re.escape(definition['account'])+r':role/[A-Za-z0-9+=,.@_/-]+',role):raise ValueError('explicit role in approved account required; no fallback')
    return {'role_arn':role,'consumer':caller,'permission_evaluated':False}
```

