def summarize(expected,snapshot):
    if not isinstance(expected,list) or any(not isinstance(i,str) or not i for i in expected) or len(expected)!=len(set(expected)):raise ValueError('unique explicit logical IDs required')
    detection=snapshot['detection_status']
    if detection not in ('DETECTION_COMPLETE','DETECTION_FAILED','DETECTION_IN_PROGRESS'):raise ValueError('unknown detection status')
    rows={}
    for row in snapshot['resources']:
        ident=row['logical_id'];status=row['status']
        if ident not in expected or ident in rows or status not in ('IN_SYNC','MODIFIED','DELETED','NOT_CHECKED'):raise ValueError('ambiguous resource or drift status')
        rows[ident]=status
    if detection!='DETECTION_COMPLETE':return {'assessment':'incomplete','checked':[],'drifted':[],'unverified':sorted(expected)}
    unverified=sorted(i for i in expected if i not in rows or rows[i]=='NOT_CHECKED')
    checked=sorted(i for i in rows if rows[i]!='NOT_CHECKED')
    drifted=sorted(i for i in rows if rows[i] in ('MODIFIED','DELETED'))
    assessment='drift_detected' if drifted else 'incomplete' if unverified else 'in_sync_in_declared_scope'
    return {'assessment':assessment,'checked':checked,'drifted':drifted,'unverified':unverified}
